// Rule Kategori (Tahap 3): map skor -> kategori berdasarkan ambang
const items = [];
for (const item of $input.all()) {
  const d = item.json;
  let ambangHigh = 80, ambangLow = 40;
  if (!isNaN(parseInt(d.ambangHigh,10))) ambangHigh = parseInt(d.ambangHigh,10);
  if (!isNaN(parseInt(d.ambangLow,10))) ambangLow = parseInt(d.ambangLow,10);
  let skor = Number(d.skorLLM ?? d.skor ?? 0);
  if (isNaN(skor)) skor = 0;
  skor = Math.max(0, Math.min(100, skor));
  let kategori, label, alasan;
  if (skor >= ambangHigh) { kategori='High'; label='Layak Lanjut'; alasan='Skor '+skor+' ≥ '+ambangHigh; }
  else if (skor >= ambangLow) { kategori='Medium'; label='Perlu Ditinjau'; alasan='Skor '+skor+' di antara '+ambangLow+'-'+ambangHigh; }
  else { kategori='Low'; label='Belum Sesuai'; alasan='Skor '+skor+' < '+ambangLow; }
  items.push({ json: { ...d, skorLLM: skor, kategori, kategoriLabel: label, alasanKategori: alasan } });
}
return items;

// Fallback LLM: parse response & gabungkan, atau rule-based jika gagal
const items = [];
for (const item of $input.all()) {
  const d = item.json;
  const body = d.body || d.json || {};
  let parsed = null;
  const raw = (body.choices && body.choices[0] && body.choices[0].message && body.choices[0].message.content) || '';
  try { parsed = JSON.parse(raw); } catch (_) {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { parsed = JSON.parse(m[0]); } catch (_2) { parsed = null; } }
  }
  let skor = 0, skillTerdeteksi = '', alasan = '', notes = '', errorFlag = d.errorFlag || '';
  if (parsed) {
    skor = Number(parsed.skor); if (isNaN(skor)) skor = 0;
    skillTerdeteksi = Array.isArray(parsed.skill_terdeteksi) ? parsed.skill_terdeteksi.join(', ') : String(parsed.skill_terdeteksi || '');
    alasan = String(parsed.alasan_llm || '');
    notes = String(parsed.enrichment_notes || '');
  } else {
    errorFlag = 'llm_parse_error';
  }
  items.push({ json: { ...d, skorLLM: skor, skillTerdeteksi, alasanSkor: alasan, enrichmentNotes: notes, errorFlag } });
}
return items;

// Tulis ke Sheets (Data Kandidat). Dedup: cek email+lowongan.
// Asumsi: Google Sheets node nantinya di-append. Di sini kita siapkan baris.

function getVals(d) {
  return [
    new Date().toISOString(),      // Timestamp
    d.nama || '',                  // Nama
    d.email || '',                 // Email
    d.noHP || '',                  // No HP
    d.lowongan || '',              // Lowongan
    d.urlCV || '',                 // URL CV
    d.ruleCheck || '',             // Rule Check
    d.alasanRuleCheck || '',       // Alasan Rule Check
    d.skillTerdeteksi || '',       // Skill Terdeteksi
    d.skorLLM ?? '',               // Skor LLM
    d.alasanSkor || '',            // Alasan Skor
    d.enrichmentNotes || '',       // Enrichment Notes
    d.kategori || '',              // Kategori
    d.alasanKategori || '',        // Alasan Kategori
    d.kategoriLabel || '',         // Kategori Label
    'N/A',                         // Status Notifikasi HR
    'N/A',                         // Status Auto-Reply
    '',                            // Waktu Auto-Reply
    d.errorFlag || ''              // Error Flag
  ];
}

const items = [];
for (const item of $input.all()) {
  const d = item.json;
  items.push({
    json: {
      ...d,
      sheetRow: getVals(d),
      autoReplyStatus: 'N/A'
    }
  });
}
return items;

// Kategori -> status email yang harus dikirim
const items = [];
for (const item of $input.all()) {
  const d = item.json;
  let notifStatus = 'N/A';
  let autoReplyStatus = 'N/A';
  if (d.kategori === 'High' || d.kategori === 'Medium') { notifStatus = 'Perlu'; autoReplyStatus = 'N/A'; }
  else if (d.kategori === 'Low') { notifStatus = 'N/A'; autoReplyStatus = 'Pending'; }
  items.push({ json: { ...d, notifStatus, autoReplyStatus } });
}
return items;

// Tulis Audit Log (append-only)
const items = [];
for (const item of $input.all()) {
  const d = item.json;
  items.push({
    json: {
      timestamp: new Date().toISOString(),
      eventType: d.eventType || 'pipeline_end',
      emailKandidat: d.email || '',
      lowongan: d.lowongan || '',
      detail: 'Kandidat ' + (d.nama || '') + ' → kategori ' + (d.kategori || '') + ' (skor ' + (d.skorLLM ?? '') + ')',
      status: 'Success'
    }
  });
}
return items;
